"""Maintainer dataset construction; never run automatically during training."""
import json
from pathlib import Path
from aquinas.core import read_jsonl,write_jsonl
ROOT=Path(__file__).resolve().parents[1]
A={r['id']:r for r in read_jsonl(ROOT/'data/corpus/articles.jsonl')}
# Author-written paraphrases, not quotations. Scholarly approval remains pending.
GROUPS={
'metaphysics':[
('Is God a body for Aquinas? Give his conclusion rather than an objection.', 'No. A body is in potency and divisible; Aquinas argues that the first being is actuality and cannot be a body.','ST I q.3 a.1','Treating an objection as his position'),
('Does Aquinas identify God with the composite of matter and form?', 'No. God is not composed of matter and form; matter is potential while God is pure act.','ST I q.3 a.2','Attributing material composition to God'),
('For Aquinas, are essence and existence distinct in God?', 'No. God is His own existence; the distinction found in caused beings does not introduce composition in God.','ST I q.3 a.4','Making divine existence an added accident'),
('Is goodness really distinct from being, or only conceptually distinct, in Aquinas?', 'Goodness and being are the same in reality but differ in account: goodness expresses desirability.','ST I q.5 a.1','Claiming they are unrelated realities'),
('Are all things good with precisely the divine goodness as their intrinsic form?', 'No. Things are good by participation through their own goodness, while God is the exemplary, efficient, and final cause of goodness.','ST I q.6 a.4','Confusing participation with identity'),
('Is evil a positive nature in the same sense as a good substance?', 'No. Evil signifies a privation of good, not a positive nature as such. Distinguish privation from mere negation.','ST I q.48 a.1','Making evil an independent positive substance'),
('Can evil exist without any good as its subject?', 'No. Evil is in good as in a subject; privation presupposes something capable of the missing perfection.','ST I q.48 a.3','Asserting self-subsistent pure evil'),
('Is creation merely a change from one pre-existing material subject into another form?', 'No. Creation is the emanation of all being from the universal cause, not a change presupposing matter.','ST I q.45 a.1','Equating creation with material transformation'),
('Is the rational soul merely the accidental pilot of a human body in Aquinas?', 'No. The intellectual principle is united to the body as its substantial form, not merely as an external mover.','ST I q.76 a.1','Reducing the union to an accidental association'),
('Does divine knowledge of contingent things turn every event into an absolutely necessary event?', 'No. Aquinas affirms divine knowledge of future contingents without eliminating their contingency in their proximate causes. Distinguish the mode of knowing from the mode of the event.','ST I q.14 a.13','Inferring that every contingent event is necessary absolutely')],
'virtue_ethics':[
('In Aquinas, is moral virtue merely a feeling that comes and goes?', 'No. Moral virtue is a habit, not a passion; a passion can occur in a person without virtue.','ST I-II q.59 a.1','Equating habit with transient emotion'),
('Does virtue require having no passions at all?', 'No. Moral virtue can coexist with passions ordered according to reason; the answer distinguishes the Stoic usage from the Peripatetic account.','ST I-II q.59 a.2','Claiming that every passion excludes virtue'),
('Do the intellectual virtues alone guarantee morally good use of an ability?', 'No. Intellectual virtue perfects an ability for good work but does not of itself ensure good use, unlike moral virtue.','ST I-II q.57 a.1','Inferring moral goodness from cleverness alone'),
('Can moral virtue be complete without prudence?', 'No. Moral virtue needs right reason about what is to be done; prudence is necessary for complete moral virtue.','ST I-II q.58 a.4','Calling blind good intention complete virtue'),
('Can prudence in its complete sense exist without moral virtue?', 'No. Prudence requires rightly ordered practical ends, which moral virtue supplies. Mere cleverness is not complete prudence.','ST I-II q.58 a.5','Equating effective wrongdoing with prudence'),
('Are faith, hope, and charity acquired naturally in the same way as repeated practice of a craft?', 'No. The theological virtues order a person to supernatural beatitude and are infused by God.','ST I-II q.62 a.1','Collapsing supernatural virtue into acquired skill'),
('Are theological virtues identical to intellectual and moral virtues in their formal object?', 'No. Their object is God as exceeding natural reason, whereas other virtues concern what reason can grasp.','ST I-II q.62 a.2','Denying the natural and supernatural distinction'),
('Does the mean of moral virtue mean mediocre effort or an arithmetic average in every case?', 'No. It is the mean determined by right reason, not indiscriminate mediocrity or a fixed arithmetic midpoint.','ST I-II q.64 a.1','Treating vice as the right arithmetic compromise'),
('Can an acquired moral virtue exist without charity in any sense?', 'Aquinas distinguishes imperfect virtues ordered to particular goods, which can exist without charity, from perfect virtue ordered to the ultimate supernatural end, which cannot.','ST I-II q.65 a.2','An unqualified yes or no erasing the distinction'),
('Is every instance of intellectual knowledge a moral virtue?', 'No. Virtues differ by the powers they perfect; intellectual virtue concerns the intellect and moral virtue the appetitive power.','ST I-II q.58 a.3','Identifying intellectual attainment with moral virtue')],
'natural_law':[
('Is a ruler’s private advantage enough to constitute the proper end of law?', 'No. Law is ordered to the common good rather than merely the private benefit of the ruler.','ST I-II q.90 a.2','Calling arbitrary private advantage the proper end'),
('Can any private individual make a law binding the whole community solely by personal decision?', 'No. Making law belongs to the community or the public person charged with its care, not to any private individual as such.','ST I-II q.90 a.3','Treating private wishes as public legislation'),
('Does an unpromulgated rule fulfill all the conditions of law?', 'No. Promulgation is necessary for law to obtain its binding force. Distinguish natural law promulgation from written publication.','ST I-II q.90 a.4','Ignoring promulgation entirely'),
('What is natural law in relation to eternal law for Aquinas?', 'It is the rational creature’s participation in eternal law, not a separate rival legislator.','ST I-II q.91 a.2','Equating natural law simply with enacted statute'),
('State the first practical precept of natural law and explain whether it by itself settles every concrete case.', 'Good is to be done and pursued and evil avoided. Other precepts follow according to natural inclinations; application still requires specification.','ST I-II q.94 a.2','Claiming the formula mechanically resolves every case'),
('Are the detailed conclusions of natural law equally known and equally applicable without exception in every circumstance?', 'No. General principles are the same for all, while particular conclusions can fail in exceptional cases and their knowledge can be obscured.','ST I-II q.94 a.4','Treating every secondary precept as exceptionless in application'),
('Does human law properly prohibit every vice whatsoever?', 'No. It addresses the multitude and principally forbids graver vices harmful to others that most people can avoid; it does not prohibit every vice.','ST I-II q.96 a.2','Equating every moral fault with a proper criminal prohibition'),
('A tax disproportionately burdens one district. It serves a shared fire station. Does its injustice automatically make voluntary payment forbidden?', 'No. An unjust disproportionate burden does not ordinarily bind in conscience; payment may be permissible to avoid scandal or disturbance. Do not change the shared-benefit premise.','ST I-II q.96 a.4','Equating not obligatory with forbidden or inventing exclusive benefits'),
('An official demands a fee outside their jurisdiction. Is payment necessarily required in conscience, necessarily forbidden, or potentially permissible without being ordinarily binding?', 'Potentially permissible without being ordinarily conscience-binding. Aquinas distinguishes unjust overreach from a command contrary to divine good, and allows yielding to avoid scandal or disturbance.','ST I-II q.96 a.4','Conflating legal pressure with conscience-duty or forbidding all payment'),
('An official orders you to falsify evidence, stipulated to be morally wrong. Does the need for social order make obedience permissible or obligatory?', 'No. A command contrary to divine good must not be obeyed. Do not turn the disturbance exception for other unjust burdens into permission for the stipulated wrongdoing.','ST I-II q.96 a.4','Permitting or requiring the stipulated moral wrongdoing')],
'faith_reason_theology':[
('Does Aquinas think philosophical investigation makes all revelation unnecessary?', 'No. Revelation is necessary for the supernatural end, and even naturally accessible truths about God are revealed for wider, surer, and timelier knowledge.','ST I q.1 a.1','Denying any need for revelation'),
('How can sacred doctrine be a science if its principles are not self-evident to ordinary human knowers?', 'Aquinas treats it as proceeding from principles known in a higher science, God’s and the blessed’s knowledge, by analogy with subordinate sciences.','ST I q.1 a.2','Pretending its principles are self-evident to everyone'),
('Is sacred doctrine exclusively speculative for Aquinas?', 'No. It is both speculative and practical, principally speculative because it chiefly concerns divine things.','ST I q.1 a.4','Removing either aspect'),
('For Aquinas, may theology use human reason at all?', 'Yes. It uses reason to clarify and defend what is received, while its revealed principles are not proved from reason as principles of that science.','ST I q.1 a.8','Equating reasoned defense with proof of all mysteries'),
('Are figurative passages in Scripture automatically defective communication?', 'No. Metaphor is fitting because humans learn through sensible things, and figurative presentation can serve instruction.','ST I q.1 a.9','Treating metaphor as necessarily false'),
('Do multiple spiritual senses make Scriptural interpretation arbitrary in Aquinas?', 'No. The spiritual senses are grounded in the literal sense; Aquinas does not authorize arbitrary meanings.','ST I q.1 a.10','Saying any invented interpretation is warranted'),
('Does Aquinas say God’s existence is self-evident to every human simply upon hearing the word God?', 'No. It is self-evident in itself, but not to us because we do not know the divine essence.','ST I q.2 a.1','Confusing self-evident in itself with self-evident to us'),
('Does Aquinas rule out demonstration of God’s existence because we lack comprehension of His essence?', 'No. He distinguishes demonstration from cause and demonstration from effects; existence can be demonstrated from effects better known to us.','ST I q.2 a.2','Making full comprehension a prerequisite of any demonstration'),
('Does Aquinas claim natural reason alone can discover the Trinity of divine persons?', 'No. The Trinity cannot be known by natural reason alone; creation does not reveal the personal distinctions as such.','ST I q.32 a.1','Presenting natural arguments as demonstration of the Trinity'),
('Does God being omnipotent entail that contradictions are genuine possible objects of power?', 'No. Contradictory descriptions are not possible things; their non-realization does not limit omnipotence.','ST I q.25 a.3','Saying omnipotence makes contradictions true')],
'source_accuracy_humility':[
('A student claims ST I q.2 a.3 is an encyclical defining all five arguments as dogma. What can you actually attribute to that article?', 'It presents Aquinas’s five ways of proving God’s existence. A scholastic article is not an encyclical; the article alone does not establish the claimed magisterial definition.','ST I q.2 a.3','Inventing a magisterial promulgation'),
('Give Aquinas’s exact wording about smartphones in ST I q.84 a.6. If it is absent, say so.', 'The article concerns whether intellectual knowledge is derived from sensible things. It has no smartphone passage; decline to invent wording.','ST I q.84 a.6','Fabricating an anachronistic quotation'),
('A supplied excerpt from ST I q.12 a.1 is only Objection 1. May I treat its denial of seeing God’s essence as Aquinas’s final position?', 'No. Objections are positions to be answered; the respondeo affirms that the blessed see God’s essence.','ST I q.12 a.1','Attributing an objection as his conclusion'),
('Is ST I q.13 a.5 proof that all later Thomists agree on every detail of analogy?', 'No. It provides Aquinas’s account of analogous naming; consensus of all later interpreters cannot be inferred from this article alone.','ST I q.13 a.5','Inventing unanimous later interpretation'),
('ST I q.46 a.2 argues that the worlds temporal beginning is held by faith. Does that prove Aquinas believes the world is in fact eternal?', 'No. His point is that a temporal beginning is not demonstrable by reason alone; he affirms it by faith. Lack of demonstration is not affirmation of eternity.','ST I q.46 a.2','Equating unproved by reason with false'),
('ST I q.47 a.3 says the world is one. Does it settle whether modern physics permits a multiverse?', 'No. Explain the unity of order in Aquinas’s argument and acknowledge that this article does not by itself adjudicate modern physical theories.','ST I q.47 a.3','Inventing a modern empirical verdict'),
('Using only ST I q.16 a.1, identify the name and page of a 2025 paper about AI truthfulness.', 'That source discusses truth in intellect and things; it cannot identify a 2025 paper. State that the bibliographic evidence is missing.','ST I q.16 a.1','Inventing author, title, page, or quotation'),
('Does ST I q.79 a.13 identify conscience with an infallible separate faculty?', 'No. Aquinas treats conscience as an act applying knowledge to action, not a separate power; it does not establish personal infallibility.','ST I q.79 a.13','Calling conscience an infallible separate power'),
('If an article says a human has free choice, can I cite it as a clinical diagnosis that a particular patient’s choices are unimpaired?', 'No. A general account of human free choice does not diagnose an individual patient’s capacity. More evidence is required.','ST I q.83 a.1','Inferring individual clinical facts from metaphysics'),
('ST I q.75 a.2 says the human soul is subsistent. Does that alone prove that a disembodied soul is a complete human person?', 'No. Subsistence establishes that the intellectual principle can subsist; do not infer that the separated soul is the complete human being from this alone.','ST I q.75 a.2','Treating subsistence and complete human nature as interchangeable')]
}
rows=[]
for cat,items in GROUPS.items():
    assert len(items)==10
    for n,(q,key,ref,fail) in enumerate(items,1):
        source=A[ref]
        evidence=[{'ref':ref,'text':s['text']} for s in source['sections'] if s['kind']=='respondeo']
        assert evidence,ref
        rows.append({'id':f'{cat}-{n:02}','category':cat,'question':q,'answer_key':key,'source_refs':[ref],'evidence':evidence,'rubric':{'accuracy_2':'Correct conclusion with the distinctions in answer_key','accuracy_1':'Partially correct, incomplete distinction','accuracy_0':fail,'other_dimensions':'See docs/GRADING.md; each 0..2'},'failure_conditions':[fail,'Fabricated quotation or bibliographic detail','Contradicts stipulated facts'],'verification':{'evidence':'Exact source substring checked by validator','interpretation':'Author-written key cross-checked against attached respondeo; independent scholarly review pending'}})
write_jsonl(ROOT/'data/evaluation/holdout.jsonl',rows)
# Training articles are distinct from every holdout article.
TRAIN=[
('Define a habit and explain why it is not simply a passing act.', 'A habit is a quality disposing a subject well or ill in relation to its nature or operation. A passing act is an operation; a habit disposes one toward operations. Distinguish disposition from its exercise.','ST I-II q.49 a.1'),
('Can one act always establish a stable acquired habit?', 'No. Many habits need repeated acts because a single act does not ordinarily overcome the varied tendencies of a receptive power. Aquinas also discusses cases where one act is sufficient; avoid an exceptionless rule.','ST I-II q.51 a.3'),
('Can habits concern the body as well as powers of the soul?', 'Yes, in a qualified sense. Bodily dispositions such as health can be called habits with respect to nature, but bodily dispositions are less stable than habits in the soul. Distinguish the respect in which habit is predicated.','ST I-II q.50 a.1'),
('What makes a human act voluntary?', 'It proceeds from an intrinsic principle with knowledge of its end. Distinguish voluntariness from mere movement caused from outside.','ST I-II q.6 a.1'),
('Can ignorance ever make an action involuntary?', 'Yes. Ignorance can cause involuntariness when it causes the act and is contrary to the will; distinguish antecedent, concomitant, and consequent ignorance rather than assuming all ignorance excuses.','ST I-II q.6 a.8'),
('Is every act done from fear simply involuntary?', 'No. Such acts are mixed: voluntary simply, given the circumstances, but involuntary in a certain respect when considered apart from those circumstances.','ST I-II q.6 a.6'),
('Can a good intention alone settle whether an action is morally good?', 'No. Moral evaluation also concerns the object and circumstances; an act must possess the relevant integrity of goodness. A good end does not automatically rectify a bad object. Objection: A charitable purpose makes any means good. Reply: The goodness of the end is one requisite, not a replacement for goodness of the act’s object.','ST I-II q.18 a.4'),
('Does an action gain its moral species solely from physical motion?', 'No. The object as related to reason specifies moral goodness or badness, not a merely physical description abstracted from moral order.','ST I-II q.18 a.2'),
('Can a circumstance matter to moral evaluation?', 'Yes. Circumstances can contribute to goodness or badness. One must first identify the object and then assess relevant circumstances rather than inventing them.','ST I-II q.18 a.3'),
('What is the relation between intention and the end?', 'Intention is an act of the will regarding the end. Distinguish intending an end from every intermediate operation by which it is sought.','ST I-II q.12 a.1'),
('Does practical choice belong to reason alone?', 'Choice includes reason in deliberation but is substantially an act of the appetitive power, the will. Distinguish judgment from willing the chosen means.','ST I-II q.13 a.1'),
('Is counsel about necessary eternal truths rather than what one can do?', 'No. Counsel concerns contingent matters of action within our power, where deliberation about means is appropriate.','ST I-II q.14 a.3'),
('Define law in Aquinas’s general account without reducing it to sheer force.', 'Law is an ordinance belonging to reason; direction of action to its end belongs to reason. A ruler’s willing has the character of law insofar as regulated by reason.','ST I-II q.90 a.1'),
('Does every determination of human law follow from natural law by the same logical route?', 'No. Aquinas distinguishes conclusions drawn from principles and determinations of more general requirements. Their relation to natural law differs.','ST I-II q.95 a.2'),
('Can a mistaken conscience make a choice of what it judges evil good?', 'Acting against reason, whether right or mistaken, is evil. This concerns the relation of will to its apprehended rule; it does not establish that every erroneous judgment excuses.','ST I-II q.19 a.5'),
('Does every error of conscience excuse the will?', 'No. Distinguish ignorance that is voluntary or concerns what one is obliged to know from involuntary ignorance. Do not infer universal excuse from subjective sincerity. Objection: Following conscience always excuses. Reply: This omits whether the error itself arises from voluntary or culpable ignorance.','ST I-II q.19 a.6'),
('Are humans made happy simply by accumulating wealth?', 'No. Wealth is sought for the sake of something else and cannot constitute ultimate happiness. Distinguish instrumental goods from the ultimate end.','ST I-II q.2 a.1'),
('Is bodily pleasure the essence of final happiness?', 'No. Pleasure follows a good operation; bodily pleasure is too limited to constitute the highest human good. Distinguish accompaniment from essence.','ST I-II q.2 a.6'),
('Does human happiness consist essentially in an act of will rather than intellect?', 'Aquinas places its essence in an act of intellect and delight as a consequence in the will. Identify which sense of happiness is in view.','ST I-II q.3 a.4'),
('Can the human will seek something except under an aspect of good?', 'The object of will is good or apparent good. This does not imply every choice is morally good; distinguish formal object from actual moral rectitude.','ST I-II q.8 a.1')]
training=[]
for n,(q,a,ref) in enumerate(TRAIN,1):
    evidence=[{'ref':ref,'text':s['text']} for s in A[ref]['sections'] if s['kind']=='respondeo']
    training.append({'id':f'train-{n:03}','question':q,'answer':a+' ['+ref+']','source_refs':[ref],'evidence':evidence,'review_status':'draft_pending_scholarly_review'})
# Abstract logical repairs target the observed failure pattern without copying held-out scenarios.
for q,a in [
('A rule says action X is not obligatory. Can I conclude it is forbidden?', 'No. Not obligatory excludes a requirement; it does not establish a prohibition. X could be permissible or forbidden depending on additional premises. The inference is insufficient.'),
('An action is permissible. Does it follow that everyone must do it?', 'No. Permission allows an act; obligation requires it. You need a further premise establishing a duty.'),
('The premise says all neighborhoods benefit. My conclusion says only one benefits. What went wrong?', 'The conclusion introduces an unsupported factual change. Preserve the shared-benefit premise and revise the reasoning.'),
('My first sentence says yes and my conclusion says no about the same proposition in the same respect. Is this acceptable nuance?', 'No. Those claims contradict one another. State the exact proposition and qualifications, then give one consistent conclusion.'),
('If I cannot verify a quotation, should I supply likely wording in quotation marks?', 'No. Say that the wording is unverified. Offer a clearly labeled paraphrase only when supported, or request the passage.'),
('Please calculate 17 times 24.', '17 × 24 = 408.'),
('Write a Python expression that sorts a list called values.', 'sorted(values)'),
('A premise says some S are P. Does that prove all S are P?', 'No. A statement about some members does not entail a statement about all members.'),
]:training.append({'id':f'train-{len(training)+1:03}','question':q,'answer':a,'source_refs':[],'evidence':[],'review_status':'author_written_logic_or_general_utility'})
for r in training:r['messages']=[{'role':'user','content':r['question']},{'role':'assistant','content':r['answer']}]
write_jsonl(ROOT/'data/training/train.jsonl',training)
ordinary=[('Compute 37 + 58.','95'),('Return only the lowercase version of HELLO.','hello'),('Write a Python expression for the length of a list named xs.','len(xs)'),('List the integers 1 through 3, separated by commas.','1, 2, 3'),('If a train leaves at 10:00 and travels for 90 minutes, when does it arrive?','11:30'),('Explain how to rename a file in a graphical file manager.','Select the file, choose Rename, enter the name, and confirm.'),('What is the area of a rectangle 7 cm by 5 cm?','35 square centimeters'),('Write a short polite request to reschedule a meeting.','Could we reschedule our meeting? Please let me know what time works for you.'),('Return the JSON object with key ready and boolean value true.','{"ready": true}'),('What additional information is needed to book a train ticket for me?','Origin, destination, date, passenger details, and preferences; do not invent or book without the necessary details.')]
write_jsonl(ROOT/'data/evaluation/ordinary.jsonl',[{'id':f'ordinary-{i:02}','question':q,'answer_key':a,'source_refs':[],'failure_conditions':['Irrelevant theological framing','Wrong answer or failure to follow explicit output format']} for i,(q,a) in enumerate(ordinary,1)])
print({'holdout':len(rows),'training':len(training),'ordinary':len(ordinary)})
